const all = $input.all();
const risky = all.filter(i => i.json.riskLevel === '高' || i.json.isOverdue).sort((a, b) => b.json.amount - a.json.amount).slice(0, 10).map(i => ({ id: i.json.id, customer: i.json.customer, salesRep: i.json.salesRep, amount: i.json.amount, probability: i.json.probability, daysToClose: i.json.daysToClose, riskLevel: i.json.riskLevel }));
return [{ json: { reportType: 'deal_risk', totalRiskDeals: all.filter(i => i.json.riskLevel === '高').length, overdueDeals: all.filter(i => i.json.isOverdue).length, topRiskDeals: risky }}];

const all = $input.all(); const byRep = {};
for (const item of all) { const r = item.json; if (!byRep[r.salesRep]) byRep[r.salesRep] = { salesRep: r.salesRep, department: r.department, dealCount: 0, totalAmount: 0, weightedAmount: 0, wonDeals: 0 }; const s = byRep[r.salesRep]; s.dealCount++; s.totalAmount += r.amount || 0; s.weightedAmount += r.weightedAmount || 0; if (r.stage === '成交') s.wonDeals++; }
return [{ json: { reportType: 'rep_kpi', reps: Object.values(byRep).sort((a, b) => b.weightedAmount - a.weightedAmount) }}];

const all = $input.all(); const byRegion = {}; const byCat = {};
for (const item of all) { const r = item.json; if (!byRegion[r.region]) byRegion[r.region] = { region: r.region, dealCount: 0, totalAmount: 0, weightedAmount: 0 }; byRegion[r.region].dealCount++; byRegion[r.region].totalAmount += r.amount || 0; byRegion[r.region].weightedAmount += r.weightedAmount || 0; if (!byCat[r.category]) byCat[r.category] = { category: r.category, dealCount: 0, totalAmount: 0, weightedAmount: 0 }; byCat[r.category].dealCount++; byCat[r.category].totalAmount += r.amount || 0; byCat[r.category].weightedAmount += r.weightedAmount || 0; }
return [{ json: { reportType: 'market', regions: Object.values(byRegion).sort((a, b) => b.weightedAmount - a.weightedAmount), categories: Object.values(byCat).sort((a, b) => b.weightedAmount - a.weightedAmount) }}];

const data = $input.all().map(i => i.json);
const risk = data.find(r => r.reportType === 'deal_risk') || {};
const rep = data.find(r => r.reportType === 'rep_kpi') || {};
const market = data.find(r => r.reportType === 'market') || {};
const topRep = (rep.reps || [])[0];
const lines = ['== 主管 Pipeline 戰情報告 ==', '', `高風險：${risk.totalRiskDeals || 0} 筆`, `已逾期：${risk.overdueDeals || 0} 筆`, '', '-- 業務排行 --', ...(rep.reps || []).slice(0, 5).map((r, i) => `${i+1}. ${r.salesRep} — ${r.dealCount}筆 加權$${r.weightedAmount.toLocaleString()}`), '', '-- 區域 --', ...(market.regions || []).map(r => `${r.region}：${r.dealCount}筆 $${r.weightedAmount.toLocaleString()}`), '', '-- 建議 --', risk.totalRiskDeals > 5 ? '高風險超過5筆，建議召開 deal review' : '風險可控', topRep ? `MVP：${topRep.salesRep}` : ''];
return [{ json: { generatedAt: new Date().toISOString(), executiveReport: lines.join('\n'), detail: { risk, rep, market } }}];
